// Build a minimal SLIST-compatible type layout and exercise SLIST_FIRST
struct SNode { int v; struct { SNode *sle_next; } link; } n[4];
struct SHead { SNode *slh_first; } h;
// Initialize head to empty
h.slh_first = nullptr;
// Randomly create a small list of 0..3 elements
unsigned int r = *FUZZ_PARAM(unsigned int);
int cnt = (int)(r % 4);
for (int i = 0; i < cnt; ++i) { n[i].link.sle_next = (i+1 < cnt) ? &n[i+1] : nullptr; }
if (cnt > 0) h.slh_first = &n[0];
// Call target macro
SNode *first = SLIST_FIRST(&h);
// Validate property: if empty then first is NULL; else first equals head.slh_first
if (cnt == 0) { FUZZ_ASSERT(first == nullptr, "SLIST_FIRST must be NULL on empty list"); }
else { FUZZ_ASSERT(first == &n[0], "SLIST_FIRST must return the first node"); }

// SLIST_END is defined as NULL. Validate it behaves as end sentinel.
(void)SLIST_END((struct SHead *)nullptr); // compile-time usage; value is NULL
// Use it in a comparison with a constructed list head
struct SNode { int v; struct { SNode *sle_next; } link; } a;
struct SHead { SNode *slh_first; } h;
h.slh_first = nullptr;
FUZZ_ASSERT(SLIST_END(&h) == nullptr, "SLIST_END must expand to NULL");

// Build minimal SLIST layout and exercise SLIST_EMPTY
struct SNode { int v; struct { SNode *sle_next; } link; } n0, n1;
struct SHead { SNode *slh_first; } h;
// Case 1: empty
h.slh_first = nullptr;
FUZZ_ASSERT(SLIST_EMPTY(&h) != 0, "SLIST_EMPTY must be true for empty list");
// Case 2: non-empty
n0.link.sle_next = &n1; n1.link.sle_next = nullptr; h.slh_first = &n0;
FUZZ_ASSERT(SLIST_EMPTY(&h) == 0, "SLIST_EMPTY must be false for non-empty list");

// Build minimal SLIST layout and exercise SLIST_NEXT
struct SNode { int v; struct { SNode *sle_next; } link; } n[3];
struct SHead { SNode *slh_first; } h;
// Ensure a list with at least 2 nodes
for (int i = 0; i < 3; ++i) n[i].link.sle_next = nullptr;
n[0].link.sle_next = &n[1]; n[1].link.sle_next = &n[2]; h.slh_first = &n[0];
SNode *e0 = SLIST_FIRST(&h);
SNode *e1 = SLIST_NEXT(e0, link);
FUZZ_ASSERT(e1 == &n[1], "SLIST_NEXT should return the next element");
SNode *e2 = SLIST_NEXT(e1, link);
FUZZ_ASSERT(e2 == &n[2], "SLIST_NEXT should chain correctly");

// Build minimal SLIST layout and iterate using SLIST_FOREACH
struct SNode { int v; struct { SNode *sle_next; } link; } n[4];
struct SHead { SNode *slh_first; } h;
unsigned int r = *FUZZ_PARAM(unsigned int);
int cnt = (int)(r % 4);
for (int i = 0; i < cnt; ++i) { n[i].v = i; n[i].link.sle_next = (i+1<cnt)?&n[i+1]:nullptr; }
h.slh_first = (cnt>0)?&n[0]:nullptr;
int seen = 0; SNode *it;
SLIST_FOREACH(it, &h, link) { (void)it; ++seen; }
FUZZ_ASSERT(seen == cnt, "SLIST_FOREACH must visit exactly all elements");

// Build minimal SLIST layout and iterate using SLIST_FOREACH_SAFE while removing elements
struct SNode { int v; struct { SNode *sle_next; } link; } n[4];
struct SHead { SNode *slh_first; } h;
unsigned int r = *FUZZ_PARAM(unsigned int);
int cnt = (int)(r % 4);
for (int i = 0; i < cnt; ++i) { n[i].v = i; n[i].link.sle_next = (i+1<cnt)?&n[i+1]:nullptr; }
h.slh_first = (cnt>0)?&n[0]:nullptr;
int removed = 0; SNode *it, *tmp;
SLIST_FOREACH_SAFE(it, &h, link, tmp) {
    // Remove head repeatedly using safe iteration mechanics
    if (SLIST_FIRST(&h) == it) {
        // Preconditions: head must be non-NULL
        SLIST_REMOVE_HEAD(&h, link);
        ++removed;
    }
}
FUZZ_ASSERT(removed <= cnt, "Removed count cannot exceed initial size");

// Exercise SLIST_INIT to set an SLIST head empty
struct SNode { int v; struct { SNode *sle_next; } link; } dummy;
struct SHead { SNode *slh_first; } h;
h.slh_first = &dummy; // prefill with non-NULL to verify it gets cleared
SLIST_INIT(&h);
FUZZ_ASSERT(h.slh_first == NULL, "SLIST_INIT must set head first to NULL");

// Build list with at least one element and insert after it
struct SNode { int v; struct { SNode *sle_next; } link; } a, b, c;
struct SHead { SNode *slh_first; } h;
// Start with one element (a)
h.slh_first = &a; a.link.sle_next = NULL; b.link.sle_next = NULL; c.link.sle_next = NULL;
// Choose which existing element to insert after (only 'a' exists now)
SNode *after = &a;
// Insert b after a
SLIST_INSERT_AFTER(after, &b, link);
FUZZ_ASSERT(a.link.sle_next == &b, "Insertion after must link from predecessor to new element");
// Insert c after b
SLIST_INSERT_AFTER(&b, &c, link);
FUZZ_ASSERT(b.link.sle_next == &c, "Second insertion must link correctly");

// Exercise SLIST_INSERT_HEAD in empty and non-empty states
struct SNode { int v; struct { SNode *sle_next; } link; } a, b;
struct SHead { SNode *slh_first; } h;
// Empty -> insert a
h.slh_first = NULL; a.link.sle_next = (SNode*)0x1; // will be overwritten
SLIST_INSERT_HEAD(&h, &a, link);
FUZZ_ASSERT(h.slh_first == &a, "Head must point to inserted element");
FUZZ_ASSERT(a.link.sle_next == NULL, "Inserted head's next must be previous first (NULL here)");
// Non-empty -> insert b before a
SLIST_INSERT_HEAD(&h, &b, link);
FUZZ_ASSERT(h.slh_first == &b, "Head must update to newest inserted element");
FUZZ_ASSERT(b.link.sle_next == &a, "New head next must point to old head");

// Build SLIST with >=2 elements and remove after first
struct SNode { int v; struct { SNode *sle_next; } link; } a, b, c;
struct SHead { SNode *slh_first; } h;
a.link.sle_next = &b; b.link.sle_next = &c; c.link.sle_next = NULL; h.slh_first = &a;
// Preconditions: a has non-NULL next
SLIST_REMOVE_AFTER(&a, link);
FUZZ_ASSERT(a.link.sle_next == &c, "After removal, a->next must skip removed element");

// Build SLIST with >=1 element and remove head
struct SNode { int v; struct { SNode *sle_next; } link; } a, b;
struct SHead { SNode *slh_first; } h;
a.link.sle_next = &b; b.link.sle_next = NULL; h.slh_first = &a;
SLIST_REMOVE_HEAD(&h, link);
FUZZ_ASSERT(h.slh_first == &b, "Head must move to old second element");
// Remove last remaining to reach empty
SLIST_REMOVE_HEAD(&h, link);
FUZZ_ASSERT(h.slh_first == NULL, "Removing sole element yields empty list");

// Build SLIST with 3 elements and remove head and middle using SLIST_REMOVE
struct SNode { int v; struct { SNode *sle_next; } link; } a, b, c;
struct SHead { SNode *slh_first; } h;
a.link.sle_next = &b; b.link.sle_next = &c; c.link.sle_next = NULL; h.slh_first = &a;
// Remove head (elm==head)
SLIST_REMOVE(&h, &a, SNode, link);
FUZZ_ASSERT(h.slh_first == &b, "Removing head should advance head");
// Remove middle (search path exercised)
SLIST_REMOVE(&h, &b, SNode, link);
FUZZ_ASSERT(h.slh_first == &c, "Removing middle should relink predecessor to successor");
// Remove last
SLIST_REMOVE(&h, &c, SNode, link);
FUZZ_ASSERT(h.slh_first == NULL, "Removing last leaves list empty");

// Build LIST-compatible layout and exercise LIST_FIRST
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } n[3];
struct LHead { LNode *lh_first; } h;
// Empty case
h.lh_first = nullptr;
FUZZ_ASSERT(LIST_FIRST(&h) == nullptr, "LIST_FIRST must be NULL on empty");
// Non-empty
n[0].link.le_prev = &h.lh_first; n[0].link.le_next = &n[1];
n[1].link.le_prev = &n[0].link.le_next; n[1].link.le_next = nullptr;
h.lh_first = &n[0];
FUZZ_ASSERT(LIST_FIRST(&h) == &n[0], "LIST_FIRST returns first element");

// LIST_END expands to NULL
struct LHead { void *lh_first; } h; h.lh_first = nullptr;
FUZZ_ASSERT(LIST_END(&h) == NULL, "LIST_END must be NULL");

// Exercise LIST_EMPTY in empty and non-empty cases
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } n0;
struct LHead { LNode *lh_first; } h;
h.lh_first = NULL;
FUZZ_ASSERT(LIST_EMPTY(&h) != 0, "LIST_EMPTY true on empty");
// Non-empty
n0.link.le_prev = &h.lh_first; n0.link.le_next = NULL; h.lh_first = &n0;
FUZZ_ASSERT(LIST_EMPTY(&h) == 0, "LIST_EMPTY false on non-empty");

// Build LIST and exercise LIST_NEXT
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b, c;
struct LHead { LNode *lh_first; } h;
// Link a->b->c
h.lh_first = &a; a.link.le_prev = &h.lh_first; a.link.le_next = &b;
b.link.le_prev = &a.link.le_next; b.link.le_next = &c;
c.link.le_prev = &b.link.le_next; c.link.le_next = NULL;
FUZZ_ASSERT(LIST_NEXT(&a, link) == &b, "LIST_NEXT returns next");
FUZZ_ASSERT(LIST_NEXT(&b, link) == &c, "LIST_NEXT returns next");
FUZZ_ASSERT(LIST_NEXT(&c, link) == NULL, "LIST_NEXT NULL at tail");

// Build small LIST and iterate using LIST_FOREACH
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } n[4];
struct LHead { LNode *lh_first; } h;
unsigned int r = *FUZZ_PARAM(unsigned int); int cnt = (int)(r % 4);
// Build chain of cnt nodes
h.lh_first = (cnt>0)?&n[0]:NULL; for (int i=0;i<cnt;++i){ n[i].v=i; n[i].link.le_next=(i+1<cnt)?&n[i+1]:NULL; n[i].link.le_prev=(i==0)?&h.lh_first:&n[i-1].link.le_next; }
int seen=0; LNode *it; LIST_FOREACH(it, &h, link){ (void)it; ++seen; }
FUZZ_ASSERT(seen==cnt, "LIST_FOREACH must visit exactly all nodes");

// Build LIST and iterate using LIST_FOREACH_SAFE while removing elements
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b, c;
struct LHead { LNode *lh_first; } h;
// a->b->c
h.lh_first=&a; a.link.le_prev=&h.lh_first; a.link.le_next=&b;
b.link.le_prev=&a.link.le_next; b.link.le_next=&c;
c.link.le_prev=&b.link.le_next; c.link.le_next=NULL;
LNode *it,*tmp; int removed=0;
LIST_FOREACH_SAFE(it, &h, link, tmp){
    // Remove current element safely using LIST_REMOVE
    LIST_REMOVE(it, link);
    ++removed;
}
FUZZ_ASSERT(h.lh_first==NULL, "List should be empty after removing all elements");
FUZZ_ASSERT(removed==3, "All three elements must be removed");

// Exercise LIST_INIT to reset head to empty
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a;
struct LHead { LNode *lh_first; } h;
// Pre-populate
h.lh_first = &a; a.link.le_prev = &h.lh_first; a.link.le_next = NULL;
LIST_INIT(&h);
FUZZ_ASSERT(h.lh_first==NULL, "LIST_INIT must clear first pointer");

// Build LIST with one element and insert another after it
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b, c;
struct LHead { LNode *lh_first; } h;
// Start with single element 'a'
h.lh_first = &a; a.link.le_prev = &h.lh_first; a.link.le_next = NULL;
// Insert b after a
LIST_INSERT_AFTER(&a, &b, link);
FUZZ_ASSERT(a.link.le_next==&b, "a->next should be b after insertion");
FUZZ_ASSERT(b.link.le_prev==&a.link.le_next, "b->prev must point to a->next field");
// Insert c after b (tail insertion path)
LIST_INSERT_AFTER(&b, &c, link);
FUZZ_ASSERT(b.link.le_next==&c && c.link.le_prev==&b.link.le_next, "Chained insert after should update links");

// Build a LIST-compatible layout and exercise LIST_INSERT_BEFORE
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b, c, d;
struct LHead { LNode *lh_first; } h;
// Start with a->b
h.lh_first = &a; a.link.le_prev = &h.lh_first; a.link.le_next = &b;
b.link.le_prev = &a.link.le_next; b.link.le_next = NULL;
// Insert c before b (middle insertion)
LIST_INSERT_BEFORE(&b, &c, link);
FUZZ_ASSERT(a.link.le_next == &c, "Predecessor next must point to new element");
FUZZ_ASSERT(c.link.le_prev == &a.link.le_next, "New element prev must point to predecessor's next field");
FUZZ_ASSERT(c.link.le_next == &b, "New element next must be original target");
FUZZ_ASSERT(b.link.le_prev == &c.link.le_next, "Target prev must point to new element's next field");
// Insert d before current head (d becomes new head)
LIST_INSERT_BEFORE(&a, &d, link);
FUZZ_ASSERT(h.lh_first == &d, "Inserting before head must update list head");
FUZZ_ASSERT(d.link.le_next == &a && a.link.le_prev == &d.link.le_next, "Head links must be valid after insert-before-head");

// Exercise LIST_INSERT_HEAD in empty and non-empty states
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b;
struct LHead { LNode *lh_first; } h;
// Empty -> insert a
h.lh_first = NULL; a.link.le_next = (LNode*)0x1; a.link.le_prev = (LNode**)0x1; // overwritten
LIST_INSERT_HEAD(&h, &a, link);
FUZZ_ASSERT(h.lh_first == &a, "Head must point to inserted element");
FUZZ_ASSERT(a.link.le_prev == &h.lh_first, "a->prev must point to head's first field");
FUZZ_ASSERT(a.link.le_next == NULL, "Next of sole element must be NULL");
// Non-empty -> insert b before a
LIST_INSERT_HEAD(&h, &b, link);
FUZZ_ASSERT(h.lh_first == &b, "Head must update to newest inserted element");
FUZZ_ASSERT(b.link.le_next == &a && a.link.le_prev == &b.link.le_next, "Links must update when inserting new head");

// Build LIST with three elements a->b->c and remove various positions
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b, c;
struct LHead { LNode *lh_first; } h;
// Link a->b->c
h.lh_first = &a; a.link.le_prev = &h.lh_first; a.link.le_next = &b;
b.link.le_prev = &a.link.le_next; b.link.le_next = &c;
c.link.le_prev = &b.link.le_next; c.link.le_next = NULL;
// Remove middle (b)
LIST_REMOVE(&b, link);
FUZZ_ASSERT(a.link.le_next == &c && c.link.le_prev == &a.link.le_next, "Removing middle must splice neighbors");
// Remove head (a)
LIST_REMOVE(&a, link);
FUZZ_ASSERT(h.lh_first == &c && c.link.le_prev == &h.lh_first, "Removing head must advance head and fix back-pointer");
// Remove last remaining (c)
LIST_REMOVE(&c, link);
FUZZ_ASSERT(h.lh_first == NULL, "List should be empty after removing last element");

// Build LIST and exercise LIST_REPLACE for middle and head positions
struct LNode { int v; struct { LNode *le_next; LNode **le_prev; } link; } a, b, c, x, y;
struct LHead { LNode *lh_first; } h;
// Initial a->b->c
h.lh_first = &a; a.link.le_prev = &h.lh_first; a.link.le_next = &b;
b.link.le_prev = &a.link.le_next; b.link.le_next = &c;
c.link.le_prev = &b.link.le_next; c.link.le_next = NULL;
// Replace b with x
LIST_REPLACE(&b, &x, link);
FUZZ_ASSERT(a.link.le_next == &x, "Predecessor next must point to replacement");
FUZZ_ASSERT(x.link.le_prev == &a.link.le_next, "Replacement prev must point to predecessor's next field");
